// 01-crypto — password hashing (PBKDF2-SHA256), sessions, TOTP (RFC 6238), ids
FX.crypto = (() => {
  const enc = new TextEncoder();
  const dec = new TextDecoder();

  const rand = (n = 16) => crypto.getRandomValues(new Uint8Array(n));
  const hex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, "0")).join("");
  const b64url = (u8) => btoa(String.fromCharCode(...u8)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  const b64urlDecode = (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));

  // ── password: PBKDF2-SHA256, 100k iterations, 16-byte salt ──
  async function hashPassword(pw, iter = 100000) {
    const salt = rand(16);
    const key = await crypto.subtle.importKey("raw", enc.encode(pw), "PBKDF2", false, ["deriveBits"]);
    const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: iter }, key, 256);
    return `pbkdf2$${iter}$${hex(salt)}$${hex(new Uint8Array(bits))}`;
  }
  async function verifyPassword(pw, stored) {
    try {
      const [scheme, iterStr, saltHex, hashHex] = String(stored).split("$");
      if (scheme !== "pbkdf2") return false;
      const salt = Uint8Array.from(saltHex.match(/../g).map((h) => parseInt(h, 16)));
      const key = await crypto.subtle.importKey("raw", enc.encode(pw), "PBKDF2", false, ["deriveBits"]);
      const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: Number(iterStr) }, key, 256);
      return hex(new Uint8Array(bits)) === hashHex;
    } catch (e) { return false; }
  }

  // ── sessions: random opaque token ──
  const newSessionToken = () => b64url(rand(32));

  // ── recovery code: BOLT-XXXX-XXXX ──
  const newRecoveryCode = () => {
    const a = hex(rand(2)).toUpperCase(), b = hex(rand(2)).toUpperCase();
    return `BOLT-${a}-${b}`;
  };

  // ── user ids / uuids ──
  const newUid = () => b64url(rand(9));              // 12-char sub/tunnel token
  const newUuid = () => crypto.randomUUID();
  const newBotKey = () => `flk_${b64url(rand(18))}`;

  // ── TOTP (RFC 6238) — SHA-1, 30s step, ±1 window ──
  const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  function base32Encode(buf) {
    let bits = 0, val = 0, out = "";
    for (const b of buf) {
      val = (val << 8) | b; bits += 8;
      while (bits >= 5) { out += B32[(val >>> (bits - 5)) & 31]; bits -= 5; }
    }
    if (bits > 0) out += B32[(val << (5 - bits)) & 31];
    return out;
  }
  function base32Decode(str) {
    let bits = 0, val = 0; const out = [];
    for (const c of str.toUpperCase().replace(/=+$/, "").replace(/\s/g, "")) {
      const idx = B32.indexOf(c);
      if (idx < 0) continue;
      val = (val << 5) | idx; bits += 5;
      if (bits >= 8) { out.push((val >>> (bits - 8)) & 255); bits -= 8; }
    }
    return Uint8Array.from(out);
  }
  async function hmacSha1(keyBytes, msgBytes) {
    const key = await crypto.subtle.importKey("raw", keyBytes, { name: "HMAC", hash: "SHA-1" }, false, ["sign"]);
    return new Uint8Array(await crypto.subtle.sign("HMAC", key, msgBytes));
  }
  async function totpCode(secretB32, forStep = null) {
    const step = forStep ?? Math.floor(Date.now() / 30000);
    const msg = new Uint8Array(8);
    let s = step;
    for (let i = 7; i >= 0; i--) { msg[i] = s & 255; s = Math.floor(s / 256); }
    const mac = await hmacSha1(base32Decode(secretB32), msg);
    const off = mac[mac.length - 1] & 15;
    const num = ((mac[off] & 127) << 24) | (mac[off + 1] << 16) | (mac[off + 2] << 8) | mac[off + 3];
    return String(num % 1000000).padStart(6, "0");
  }
  async function totpVerify(secretB32, code) {
    const now = Math.floor(Date.now() / 30000);
    for (const d of [0, -1, 1]) {
      if ((await totpCode(secretB32, now + d)) === String(code).trim()) return true;
    }
    return false;
  }
  function newTotpSecret() { return base32Encode(rand(20)); }

  // ── recovery: verify hashed like a password ──
  return { hashPassword, verifyPassword, newSessionToken, newRecoveryCode, newUid, newUuid, newBotKey, totpCode, totpVerify, newTotpSecret, b64url, b64urlDecode, rand, hex, enc, dec };
})();


