  function capabilityReport() {
    const live = CAPS.filter((c) => c.st === "live");
    const gaps = CAPS.filter((c) => c.st === "gap");
    return { total: CAPS.length, live: live.length, gaps: gaps.length, gapList: gaps.map((g) => ({ id: g.id, fa: g.fa, plan: g.plan })) };
  }

