    const label = _b.label !== undefined ? _b.label : (_b.username !== undefined ? _b.username : _b.name);
    const planId = _b.planId || _b.plan; const days = _b.days !== undefined ? _b.days : _b.expiry_days;
    const gb = _b.gb !== undefined ? _b.gb : _b.limit_gb;
    const tags = _b.tags; const note = _b.note;
