    const ports = Array.isArray(_b.ports) ? _b.ports.join(",") : _b.ports;
    const shards = _b.shards; const loc = _b.loc !== undefined ? _b.loc : _b.location;
    const tunnel = _b.tunnel; const frag = _b.frag;
    const ips = _b.ips !== undefined ? _b.ips : (_b.clean_ips && _b.clean_ips !== "auto" ? (() => { try { return JSON.parse(_b.clean_ips).join(","); } catch (e) { return ""; } })() : undefined);
    const wa = _b.wa; const P52_EXTRA = { smart: _b.smart, auto_rotate_ip: _b.auto_rotate_ip, limit_req: _b.limit_req, max_connections: _b.max_connections, ip_limit: _b.ip_limit, tls_fp: _b.tls_fp };
    if (!String(label || "").trim()) return bad("label-required");
    let dDays = Number(days), dGb = Number(gb);
