    if (_raw.quotaGb !== undefined) b.quotaGb = _raw.quotaGb;
    if (_raw.limit_gb !== undefined) b.quotaGb = Number(_raw.limit_gb);
    if (_raw.renewDays !== undefined) b.renewDays = _raw.renewDays;
    if (_raw.expiry_days !== undefined) { b.P52_ABS_DAYS = Number(_raw.expiry_days) || 0; }
