    if (_raw.loc !== undefined) b.loc = _raw.loc;
    if (_raw.location !== undefined) b.loc = _raw.location;
    if (_raw.ports !== undefined) b.ports = Array.isArray(_raw.ports) ? _raw.ports.join(",") : _raw.ports;
    if (_raw.tunnel !== undefined) b.tunnel = _raw.tunnel;
