    try { serviceStrategies = await SF.SUPER.SVC.report(env); } catch (e) {}
    try { telegram = await SF.SUPER.TG.report(env); } catch (e) {}
    try { orchestrator = SF.SUPER.ORT.report(); } catch (e) {}
    try { let whost = null; try { whost = new URL(request.url).host; } catch (e) {} candidates = await SF.SUPER.CAND.report(env, whost); } catch (e) {}
